from lib import *
S = SS('e16')
steps = [
    step("重复的内容相隔多远,窗口就得多大才找得到。数据 = 1 MiB 页面文本 + N MiB 不可压缩的随机填充 + 同样的那 1 MiB(单份文本 zstd-3 压缩后 209800 字节),表里是“压缩后总字节减去填充”:约 209800 表示第二份被匹配掉了,约 419600 表示没找到。填充 0 MiB(重复相隔 1 MiB),windowLog 17、19、20 都没找到(466041、415169、417075),windowLog 21 起找到(209905);填充 1 MiB(相隔 2 MiB),windowLog 21 还不行(419315),22 起找到(210326);填充 4 MiB(相隔 5 MiB),windowLog 22 不行(421113),24 起找到(211459)。窗口要大于重复之间的距离。", t=tl(S(1)), done=lidx(S(1), '    1.00MiB'), mark=lidx(S(1), '    0.00MiB'), b=bars([['相隔 1 MiB,wLog 20', 417075, '417075(没找到)'], ['相隔 1 MiB,wLog 21', 209905, '209905(找到)'], ['相隔 5 MiB,wLog 22', 421113, '421113(没找到)'], ['相隔 5 MiB,wLog 24', 211459, '211459(找到)']], 430000, mark=[0, 2], done=[1, 3]), kv=KV([['相隔 1 MiB', 'windowLog 21(2 MiB)起找到'], ['相隔 5 MiB', 'windowLog 24(16 MiB)起找到'], ['规律', '窗口必须大于重复之间的距离']], ['规律'])),
    step("但窗口开得再大也不等于找得到:相隔 16 MiB 的重复,windowLog 27(128 MiB 窗口)的级别 3 仍然没找到(减去填充后 425615 字节,22 ms)——匹配搜索用的哈希表是有限的,太老的位置早被覆盖。打开长距离匹配(enable_ldm)才找到:216095 字节(37 ms)。把窗口缩到 windowLog 20(1 MiB)再开 LDM,又找不到了(425934),因为 LDM 也受窗口限制。窗口决定“允许往回看多远”,搜索结构决定“实际上能不能找到”。", t=tl(S(2)), done=lidx(S(2), 'windowLog 27 + enable_ldm'), mark=lidx(S(2), 'windowLog 27,不开 LDM'), b=bars([['wLog 27 不开 LDM', 425615, '425615'], ['wLog 27 + LDM', 216095, '216095'], ['wLog 20 + LDM', 425934, '425934']], 430000, mark=[0, 2], done=[1]), kv=KV([['wLog 27,不开 LDM', '16 MiB 外的重复没找到'], ['wLog 27 + LDM', '找到(216095)'], ['wLog 20 + LDM', '仍受窗口限制,没找到']], ['wLog 27 + LDM'])),
    step("解压端的窗口限制(流式压缩、事先不知道总大小,帧头里就声明大窗口):windowLog 22 的帧声明窗口 4 MiB,解压端 max_window_size 设成 4、64、128 MiB 都成功;windowLog 27 的帧声明 128 MiB,max_window_size 设成 4 MiB 或 64 MiB 失败(ZstdError: Frame requires too much memory for decoding),设成 128 MiB 成功;windowLog 28 的帧声明 256 MiB,连 128 MiB 也失败。命令行 zstd -d:windowLog 22 的帧成功,windowLog 28 的帧退出码 1(Decoding error (36): Frame requires too much memory for decoding),加 --long=28 才能解压。压缩端用多大的窗口,解压端就得准备多大的内存。", t=tl(S(3)), done=lidx(S(3), '命令行 zstd -d --long=28'), mark=lidx(S(3), '帧 windowLog 28,解压端 max_window_size = 128'), b=bars([['windowLog 22 帧 窗口 MiB', 4, '4'], ['windowLog 27 帧', 128, '128'], ['windowLog 28 帧', 256, '256']], 260, done=[0], mark=[2]), kv=KV([['windowLog 27 的帧', '解压限制 64 MiB 失败,128 MiB 成功'], ['windowLog 28 的帧', 'zstd -d 默认失败(退出码 1),--long=28 成功'], ['错误信息', 'Frame requires too much memory for decoding']], ['windowLog 28 的帧'])),
    step("gzip 的窗口固定 32 KiB,zstd 的窗口可调。pages 前 8 MiB(每页约 13 KiB,页面之间有共同的模板和重复的词):zlib-9 压成 1822313 字节(4.60×)。zstd 级别 3,windowLog 15(32 KiB)2175415,17 是 1864670,20 是 1660885,23 是 1676095;级别 9:1839849、1590804、1558895、1560280;级别 19:1747221、1494076、1444525、1401606。zstd 在同样的 32 KiB 窗口下比 zlib 大(级别 19 是 1747221,比 zlib-9 小 4%);加大窗口到 1 MiB 以上,级别 3 就比 zlib-9 小 9%。窗口到够用以后再加大收益很小,甚至略回落(级别 3,wLog 20 到 23)。", t=tl(S(4)), done=lidx(S(4), '      19'), mark=lidx(S(4), 'zlib-9(窗口 32 KiB)'), b=bars([['zlib-9(32 KiB 窗口)', 1822313, '1822313'], ['zstd-3 wLog 15', 2175415, '2175415'], ['zstd-3 wLog 20', 1660885, '1660885'], ['zstd-19 wLog 23', 1401606, '1401606']], 2200000, mark=[1], done=[2, 3]), kv=KV([['zlib-9', '32 KiB 窗口,1822313 字节'], ['zstd-3 窗口 32 KiB → 1 MiB', '2175415 → 1660885'], ['zstd-19 窗口 32 KiB → 8 MiB', '1747221 → 1401606']], ['zstd-3 窗口 32 KiB → 1 MiB'])),
    step("窗口与内存(独立子进程,pages 全部 19.9 MiB 用流式压缩成一个帧,级别 3):windowLog 15 压成 5407003 字节,压缩多用 13.8 MiB,流式解压多用 0.2 MiB;18:4112979,11.2,0.5;21:4173277,12.9,2.5;24:4177740,27.2,16.5;27:4172915,30.7,20.4。解压端的内存随窗口增长(0.2 → 20.4 MiB),压缩端也增长;这里压缩后的字节数在 windowLog 18 之后就不再变小(4112979 到 4177740),窗口超过数据里重复的间隔后只会多用内存。", t=tl(S(5)), done=lidx(S(5), '        27'), mark=lidx(S(5), '        15'), b=bars([['wLog 15 解压端内存 MiB', 0.2, '0.2'], ['wLog 18', 0.5, '0.5'], ['wLog 21', 2.5, '2.5'], ['wLog 24', 16.5, '16.5'], ['wLog 27', 20.4, '20.4']], 21, mark=[0], done=[4]), kv=KV([['windowLog 15', '压缩后 5407003,解压端 0.2 MiB'], ['windowLog 18', '压缩后 4112979,解压端 0.5 MiB'], ['windowLog 27', '压缩后 4172915,解压端 20.4 MiB']], ['windowLog 18'])),
    step("每个对象单独压缩,等于每次重置窗口。pages 8 MiB 切成不同大小的块各自压缩(级别 3):每块 4 KiB(2048 块)共 2705807 字节(3.10×),比整块压缩大 62.0%;16 KiB 2376431(3.53×),大 42.3%;64 KiB 2007345(4.18×),大 20.2%;256 KiB 1759232(4.77×),大 5.3%;1 MiB 1679330(5.00×),大 0.5%;整块 1670198(5.02×)。单个对象只有几 KiB 时,各自压缩损失一半以上的压缩比;攒成 256 KiB 以上才接近整体压缩。", t=tl(S(6)), done=lidx(S(6), '    1024KiB'), mark=lidx(S(6), '      4KiB'), b=bars([['每块 4 KiB', 3.10, '3.10×'], ['每块 64 KiB', 4.18, '4.18×'], ['每块 256 KiB', 4.77, '4.77×'], ['整块 8 MiB', 5.02, '5.02×']], 5.2, mark=[0], done=[3]), kv=KV([['每块 4 KiB', '比整块大 62.0%'], ['每块 64 KiB', '大 20.2%'], ['每块 1 MiB', '大 0.5%']], ['每块 4 KiB'])),
]
A = mkarte('e16', 16, '压缩原理,窗口,windowLog,长距离匹配,zstd,解压内存,gzip,分块,Python,真实验证,动画演示',
    '窗口决定压缩器能往回看多远:重复相隔 1 MiB 要 windowLog 21 才找得到;windowLog 27 也找不到相隔 16 MiB 的重复,要开长距离匹配;压缩端声明了大窗口,解压端不准备足够内存就会失败;每个 4 KiB 对象单独压缩比整体压缩大 62%。',
    '往回看得越远,压缩得越小,代价是内存。这篇量窗口多大才找得到重复、窗口开大了为什么还可能找不到、解压端为什么会报“需要太多内存”,以及每个对象单独压缩要付出多少压缩比。',
    [('windowLog 21', '重复内容相隔 1 MiB 时,zstd 级别 3 开始能匹配的最小窗口(2 MiB);windowLog 20 找不到'), ('Frame requires too much memory', '压缩端用了 windowLog 28,命令行 zstd -d 默认解压失败的错误;加 --long=28 才行'), ('62.0%', '8 MiB pages 切成 4 KiB 的块各自压缩,比整块压缩大的比例')],
    [('窗口要大于重复的间隔', '<p>匹配只能指向窗口内的内容。重复的内容相隔 1 MiB,windowLog 20(1 MiB)找不到,windowLog 21(2 MiB)才行;相隔 5 MiB 要 windowLog 24。对 gzip 来说窗口固定是 32 KiB,更远的重复统统错过。</p>'),
     ('窗口大也不一定找得到', '<p>相隔 16 MiB 的重复,级别 3 开了 windowLog 27 仍然没找到,因为搜索用的哈希表容量有限,老位置被覆盖。长距离匹配(enable_ldm)另建结构专门找远处的重复,开了才找到;但 LDM 仍受窗口限制。</p>'),
     ('解压端的代价', '<p>压缩端声明的窗口决定了解压端需要的内存。windowLog 27 的帧在解压端限制 64 MiB 时失败,windowLog 28 的帧命令行默认就解不了,要 --long=28。给别人分发压缩文件时,窗口不要开得比对方的内存大。</p>'),
     ('和 gzip 的比较', '<p>同样 32 KiB 窗口,zstd-19 比 zlib-9 只小 4%;放开窗口,zstd-3 在 1 MiB 窗口下就比 zlib-9 小 9%。zstd 比 gzip 小,窗口是原因之一。</p>'),
     ('内存', '<p>窗口越大,压缩和解压需要的内存越多(流式解压 0.2 MiB 到 20.4 MiB),但窗口超过数据中重复的间隔后,压缩后的大小就不再改善(windowLog 18 之后基本不变)。</p>'),
     ('不要每个对象单独压缩', '<p>每个对象单独压缩等于每次重置窗口。4 KiB 的块压缩比 3.10×,整块是 5.02×;块到 256 KiB 才接近(4.77×)。小对象要攒批或用字典(下一篇)。</p>')],
    steps,
    [ENV_E + '。zstandard 0.25.0(libzstd 1.5.7);第一、二节的数据由固定种子的页面文本和随机填充组成,窗口、LDM 等参数用 ZstdCompressionParameters 指定;第三节的流式帧用 compressobj 生成(声明大窗口),并用命令行 zstd 核对;第五节用独立子进程测 ru_maxrss 增量;所有字节数是确定性的,时间是单次测量',
     '没有验证:LDM 的具体参数(ldm_hash_log、ldm_min_match 等)对结果的影响;哈希表容量(hashLog)到底怎么限制了找得到的距离;压缩端 windowLog 比数据短时帧头声明窗口变小的规则(只看到了现象);其它压缩器(xz、brotli)的窗口行为;多线程压缩时各段之间的窗口共享'],
    '窗口与内存')
